from fastapi import HTTPException
import re
from pathlib import Path

def sanitize_path(path: str, error_text="A suspected LFI attack detected. The path sent to the server has suspicious elements in it!", exception_text="Invalid path!"):
    if path.strip().startswith("/") or not path:
        raise HTTPException(status_code=400, detail=exception_text)

    suspicious_patterns = re.compile(r'(\.\.+)|(/+/)')

    if suspicious_patterns.search(path) or Path(path).is_absolute():
        raise HTTPException(status_code=400, detail=exception_text)

    return path.lstrip('/')
